/**
 * Base worlds of the edit study: ordinary scenes and games a person might
 * already have open when they ask for a small change. They are generated by
 * the same offline planner as everything else.
 */

/** One base world: an id and the prompt that creates it. */
export interface BasePrompt {
  id: string;
  prompt: string;
  /** Part of the CI quick subset. */
  quick?: boolean;
}

/** The base worlds, in report order. */
export const BASES: readonly BasePrompt[] = Object.freeze([
  { id: 'camp', prompt: 'a cozy forest camp with a campfire and tents', quick: true },
  { id: 'village', prompt: 'a medieval village with a windmill' },
  { id: 'farm', prompt: 'a farm with a barn, a tractor and cows' },
  { id: 'beach', prompt: 'a beach with umbrellas and a lighthouse' },
  { id: 'street', prompt: 'a city street with traffic and pedestrians' },
  { id: 'park', prompt: 'a park with a fountain and benches' },
  { id: 'haunted', prompt: 'a haunted castle at night' },
  { id: 'oasis', prompt: 'a desert oasis with palm trees and a tent' },
  { id: 'cabin', prompt: 'a snowy mountain cabin with pine trees' },
  { id: 'coins', prompt: 'a coin collecting game: grab 8 coins before time runs out', quick: true },
  { id: 'parkour', prompt: 'a sky parkour course over lava', quick: true },
  { id: 'domino', prompt: 'a domino run that knocks over a bell' },
  { id: 'bowling', prompt: 'a bowling alley with ten pins' },
  { id: 'tower', prompt: 'knock down a tower of crates with a cannon' },
  { id: 'coins2', prompt: 'collect 12 coins in a forest' },
  { id: 'castle', prompt: 'a medieval castle with a moat and drawbridge' },
]);

/** The CI quick subset. */
export const QUICK_BASES: readonly BasePrompt[] = BASES.filter((b) => b.quick === true);
